# ENV_VAR=<bitwarden-secrets-manager-secret-uuid>
# One secret per line. Resolved by bin/apply at apply time and written to
# /etc/homelab-pi/zwave-js-ui.env. UUIDs are not sensitive; values never touch
# the repo. Replace the placeholder UUID below with the real bws secret id.
SESSION_SECRET=00000000-0000-0000-0000-000000000000
